  "蜂巢后": "Hive Queen",
  "嗡——有緣之人，取走吧。": "Hum — take it, fated one.",
  "三百年沒人敲我了……": "No one has struck me in three hundred years…",
  "鼎中無物，心中有物。": "Nothing in the cauldron, something in the heart.",
  "摸夠了沒？那就收下吧。": "Done touching? Then take it.",
  "天下沒有白拿的東西——這次例外。": "Nothing in the world is free — except this once.",
  "叩鼎問天，天說：給你。": "Knock the cauldron, ask the sky; the sky says: here.",
  "一袋燈芯": "A Bag of Wick",
  "神祕寶箱": "Mystery Chest",
  "只有一個「？」。打開會得到隨機獎勵（可能是武器、強化、精良強化、燈芯或燈火）": "Just one “?”. Opening it gives a random reward (weapon, upgrade, premium upgrade, wick or lamplight)",
  "除錯程式": "Debugger",
  "彩蛋箱": "Surprise Box",
  "付燈芯打開，得到一份隨機回禮（武器、強化、精良強化、燈芯或燈火）；每站一個，只能一次": "Pay wick to open for a random gift (weapon, upgrade, premium upgrade, wick or lamplight); once per stall",
  "木魚": "Wooden Fish",
  "縮圈到最小時再按 F：圓滿＝雜念清空，其他＝減半": "Press F when the ring is smallest: perfect = distractions cleared, otherwise halved",
  "木魚裂了": "The wooden fish cracked",
  "佛龕": "Shrine",
  " 功德，得到一份回禮（可能是佛寺專屬武器）；只能一次": " merit for a gift (possibly a Temple weapon); once only",
  "（已使用）": "(used)",
  "設施": "Facility",
  "古鼎": "Ancient Cauldron",
  "鼎已經安靜下來了": "The cauldron has gone quiet",
  "青銅古鼎，傳說摸一下會賜予一件寶物（只能一次）": "A bronze cauldron; legend says touching it grants a treasure (once only)",
  "華麗許願池": "Ornate Wishing Pool",
  "第 n 次投入 3×n 燈芯：3、6、9、12、15。次數越多機率與品質越高，第 5 次保底；得到獎勵後池就乾涸": "Round n costs 3×n wick: 3, 6, 9, 12, 15. More rounds raise odds and quality, the 5th is guaranteed; the pool dries up after a reward",
  "（已乾涸）": "(dried up)",
  "許願池": "Wishing Pool",
  "每次投入 4 燈芯，有機率獲得獎勵。一個池最多投 6 次，第 6 次保底（至少燈火 +1）": "4 wick per throw, with a chance of a reward. Up to 6 throws per pool; the 6th is guaranteed (at least lamplight +1)",
  "按鍵大小牌": "Button Size Sign",
  "手機專用：在「標準」與「大」兩種觸控按鈕大小之間切換（也可在暫停頁細調）": "Mobile only: switch between Standard and Large touch buttons (fine-tune on the pause page)",
  "新手教學牌": "Tutorial Sign",
  "教學面板目前關閉。再按一次開啟（電腦版，只在起始房顯示）": "The tutorial panel is off. Press again to turn on (desktop, start room only)",
  "教學面板開著，會留在畫面下方。按一下可以關閉": "The tutorial panel is on at the bottom of the screen. Press to close",
  "目前選擇：": "Current choice: ",
  "。按 F 開選單可更換或取消": "; press F to open the menu to change or cancel",
  "按 F 開選單：糖果（護送／守燈）、電玩（無盡／逃離）、未來（守燈／逃離）或隨機，選一種這一局走（也可不選）": "Press F for the menu: Candy (escort/guard), Arcade (endless/escape), Future (guard/escape) or random; pick one for this run (optional)",
  "燈塔": "Lighthouse",
  "休息中：整頓一下（商人還在上方），準備好了再按 F 繼續下一輪": "Resting: regroup (the merchant is still above); press F when ready for the next round",
  "碰一下才會開始守燈，敵人才會出現。可以先去上方找商人逛逛（每兩波會休息一次）": "Touch it to begin the defense; enemies only appear then. Visit the merchant above first (a rest every two waves)",
  "古怪機關": "Strange Device",
  "不知道做什麼用的機關，好像可以動……（只能一次）": "A device of unknown use; it seems to move… (once only)",
  "練習房・主題牌": "Practice Room: Theme Sign",
