  "目前是隨機。按一下可以指定一個主題，這一局一定會遇到（通關一次後才有）": "Currently random. Press to choose a theme you'll definitely meet this run (after clearing once)",
  "傳送陣": "Portal",
  "站上去按 F：傳送到隨機主題的超大地圖參觀。不會戰鬥，可以看看敵人、NPC 與各職業的隊友": "Stand on it and press F: teleport to a huge map of a random theme to look around. No combat — see enemies, NPCs and each class's teammates",
