  "造型機在": "The cosmetic machine opens after clearing a Long Run or DLC2 (Letter Study, Other Shore) once; you can also try it early by ticking “Test: enable cosmetic machine” on the class screen. Looks are generic shapes tinted by theme, not final art.",
  "目前紙片：": "Paper scraps now: ",
  "紙片收入（每局結算）：基本 5；通關 +10；每個新成就 +5；長線作戰每層 +3（追加層每層 +5）。": "Paper income (per run): base 5; +10 for a clear; +5 per new achievement; +3 per floor of a Long Run (+5 for extra floors).",
