  "刪除": "Delete",
  "格式：LKC1:{\"s\":部位,\"n\":名稱,\"c\":主色,\"c2\":副色,\"p\":[[x,y],…],\"q\":[[x,y],…]}；p 為主多邊形（3～16 點、座標 -24～24，原點在該部位錨點，y 向下），q 為選填的副色多邊形。": "Format: LKC1:{\"s\":part,\"n\":name,\"c\":main color,\"c2\":second color,\"p\":[[x,y],…],\"q\":[[x,y],…]}; p is the main polygon (3–16 points, coordinates −24 to 24, origin at the part's anchor, y down), q is an optional secondary polygon.",
  "機率：普通 70%、稀有 25%、傳說 5%；每 30 抽保底 1 個傳說；重複的外觀變成紙屑（普通 1、稀有 3、傳說 10）；合成價：普通 5、稀有 15、傳說 40 紙屑。抽到的外觀到「造型」頁裝備（頭飾、身衣、燈飾、小飾品四欄）。": "Odds: Common 70%, Rare 25%, Legendary 5%; a legendary is guaranteed every 30 draws; duplicates become scrap (Common 1, Rare 3, Legendary 10); fuse prices: Common 5, Rare 15, Legendary 40 scrap. Equip drawn looks on the Cosmetics page (headwear, outfit, lamp, charm).",
