  "死亡所在的房間：": "Rooms where you died: ",
  "W／S 選項目，A／D 換造型，F 返回。第一列可以直接換職業（最後一列是該職業的專屬造型）；造型只改外觀，灰色的在成就或通關後解鎖": "W/S choose a row, A/D change look, F back. The first row switches class (the last row is that class's exclusive look); looks are cosmetic only, and greyed ones unlock via achievements or clears",
  "F 返回。死因從 v2.12 開始記錄；下方的「遊玩遙測」從 v2.34 開始累積，可隨遊玩紀錄匯出匯入": "F back. Causes of death are recorded since v2.12; the “Play telemetry” below accumulates since v2.34 and can be exported/imported with play records",
  "F 返回。紙片只能用在造型機，沒有真錢，也不影響強度": "F back. Paper scraps are only for the cosmetic machine — no real money, and no effect on strength",
  "F 返回。遊玩紀錄＝成就、統計、造型、設定、遙測；匯入時與目前資料合併（取較大值）": "F back. Play record = achievements, stats, looks, settings and telemetry; importing merges with current data (taking the larger values)",
