  "10 秒內瞄準亂飄，但不停掉出燈芯": "For 10 s your aim drifts, but wicks keep dropping",
  "F 了解道場　按住 F 誦經": "F Learn about the dojo  Hold F to chant",
  "F 交出手上的武器": "F Hand over your weapon",
  "F 付 2 燈芯渡河": "F Pay 2 wicks to cross",
