  "F 側耳傾聽（會出現海妖）": "F Listen closely (sirens appear)",
  "F 加入狂歡": "F Join the revel",
  "F 布施 1 燈芯（功德 +2）": "F Give 1 wick (merit +2)",
  "F 打開盒子（獎勵＋災厄）": "F Open the box (reward + calamity)",
  "F 拆開情書": "F Open the love letter",
  "F 掛紅絲帶（5 燈芯）": "F Hang a red ribbon (5 wicks)",
