  "禮物已經拆開了": "The gift is already unwrapped",
  "花 3 燈芯換一份神祕禮物：50% 強化、30% 燈芯 +8、20% 空盒子（只有 1 燈芯）；只能一次": "Spend 3 wicks for a mystery gift: 50% upgrade, 30% wicks +8, 20% empty box (only 1 wick). One use only.",
  "F 交換（3 燈芯）": "F Exchange (3 wicks)",
  "拆開禮物：強化「": "Gift unwrapped: upgrade \"",
  "禮物盒裡有燈芯 +8": "The gift box holds wicks +8",
  "空盒子……還有一顆糖，燈芯 +1": "An empty box... and one candy, wicks +1",
  "聖誕合唱：站在合唱團旁聽 5 秒": "Christmas Carol: listen beside the choir for 5 s",
  "聖誕合唱團": "Christmas Choir",
  "站在合唱團旁邊（150 像素內）聽 5 秒，離開會倒退。聽完：燈火 +1、燈芯 +10": "Stand within 150 px of the choir and listen for 5 s; leaving rewinds the progress. When done: lamplight +1, wicks +10.",
  "靠近合唱團（": "Get close to the choir (",
  "歌聲暖暖的：燈火 +1、燈芯 +10": "The singing is warm: lamplight +1, wicks +10",
  "熱可可攤：花 6 燈芯，喝一杯暖一暖": "Hot Cocoa Stand: spend 6 wicks for a warming cup.",
  "可可賣完了": "The cocoa is sold out",
  "花 6 燈芯：燈火 +2、技能冷卻重置；只能一次": "Spend 6 wicks: lamplight +2, skill cooldown reset. One use only.",
  "F 買熱可可（6 燈芯）": "F Buy hot cocoa (6 wicks)",
  "熱可可：燈火 +2、技能冷卻重置": "Hot cocoa: lamplight +2, skill cooldown reset",
  "耶誕節（DLC5）": "Christmas (DLC5)",
  "發條玩具盒": "Clockwork Toy Box",
  "雪橇的鈴聲由遠而近，一個巨大的紅色身影擋在路中間。": "Sleigh bells draw near, and an enormous red figure blocks the road.",
  "今年的禮物……全都送不出去了。來，你替我接住它們吧！": "This year's gifts... none of them can be delivered. Here — you catch them for me!",
  "工廠的烤箱門一扇扇打開，熱氣裡走出整排薑餅人。": "The factory's oven doors swing open one by one, and a whole row of gingerbread men marches out of the steam.",
  "訂單沒做完，誰都別想走！出爐——": "The orders aren't finished — no one's leaving! Out of the oven —",
  "只要薑餅人還站著，工廠長就有糖霜護體。": "As long as gingerbread men still stand, the factory boss is shielded by frosting.",
  "玩具堆裡，一個比房子還高的木頭士兵慢慢轉過頭，發條咔啦咔啦地響。": "In the pile of toys, a wooden soldier taller than a house slowly turns its head, its clockwork clicking and clattering.",
  "咔、咔——想要我的心，就得先撬開我的嘴。": "Click, click — if you want my heart, you must pry open my mouth first.",
  "牠張開嘴巴的瞬間，是最脆弱的時候。": "The instant it opens its mouth is when it is most vulnerable.",
  "大範圍的弧形揮砍（耶誕節專屬，類似提燈刃）": "A wide arcing slash (Christmas only; similar to the Lantern Blade).",
  "單發的雪球，傷害高（耶誕節專屬，類似燈焰杖）": "A single snowball with high damage (Christmas only; similar to the Flame Staff).",
  "按住連射小鈴鐺，射速快（耶誕節專屬，類似螢火弓）": "Hold to rapid-fire tiny bells at a fast rate (Christmas only; similar to the Firefly Bow).",
  "五發冬青果散射，近距離很痛（耶誕節專屬，類似霰光杖）": "Five scattered holly berries that hurt up close (Christmas only; similar to the Scatterlight Staff).",
  "貫穿一整排敵人的冰錐（耶誕節專屬，類似穿光矛）": "An icicle that pierces an entire row of enemies (Christmas only; similar to the Piercing Spear).",
  "送不出去的禮物": "Undeliverable Gifts",
  "耶誕節：擊敗聖誕老人": "Christmas: defeat Santa Claus",
  "耶誕節：擊敗薑餅工廠長": "Christmas: defeat the Gingerbread Factory Boss",
  "撬開那張嘴": "Pry Open That Mouth",
  "耶誕節：擊敗巨型胡桃鉗": "Christmas: defeat the Giant Nutcracker",
  "聖誕小幫手": "Christmas Helper",
  "耶誕節：同一局完成許願聖誕樹與精靈工坊": "Christmas: complete both the Wishing Christmas Tree and the Elf Workshop in one run",
  "雪停了。下一個節日的鈴聲，已經在路的盡頭響起。": "The snow has stopped. The bells of the next holiday already ring at the end of the road.",
  "謝謝你替我接住了那些禮物。今年，終於有人拆開它們。": "Thank you for catching those gifts for me. This year, someone finally unwrapped them.",
  "雪地上的燈一盞一盞地熄了，只剩下你的那一盞，安靜地亮到天亮。": "The lamps on the snow go out one by one, until only yours remains, quietly burning until dawn.",
  "雪化了，草地從泥土裡探出頭。風裡有花香，也有一點點巧克力的味道。": "The snow has melted and grass peeks out of the earth. The wind carries the scent of flowers, and a faint hint of chocolate.",
  "旅人！彩蛋全被藏起來了，連蛋殼都在亂跑——幫我找回春天好嗎？": "Traveler! All the Easter eggs have been hidden, and even the eggshells are running amok — will you help me find spring again?",
  "花開得太用力，連空氣都是粉紅色的。籃子翻倒在草叢，蛋滾得到處都是。": "The flowers have bloomed so hard that even the air is pink. A basket lies overturned in the grass, and eggs have rolled everywhere.",
  "最大的那顆蛋……還沒有孵出來。牠一直在等一個敲門的人。": "The biggest egg... hasn't hatched yet. It has been waiting for someone to knock.",
  "彩蛋便條：我把最漂亮的那顆藏在最顯眼的地方，結果大家都沒找到。": "Egg note: I hid the prettiest one in the most obvious place, and nobody found it.",
  "彩蛋便條：小雞說，破殼的那一刻不是結束，是第一次看見天空。": "Egg note: the chick says that cracking out of the shell isn't the end — it's the first time you see the sky.",
  "彩蛋便條：兔子洞很深，但盡頭有一盞跟你一樣的燈。": "Egg note: the rabbit hole is deep, but at its end is a lamp just like yours.",
  "彩蛋便條：春天不是被找到的，是被一起種出來的。": "Egg note: spring isn't found — it's grown together.",
  "站在花園裡等 6 秒，花就會開": "Stand in the garden and wait 6 s, and the flowers will bloom",
  "燈芯不夠（每顆蛋 4 燈芯）": "Not enough wicks (4 wicks per egg)",
  "籃子裡的蛋全孵開了：燈火 +1、精良強化「": "All the eggs in the basket hatched: lamplight +1, premium upgrade \"",
