  "（歷史最遠 ": " (farthest ever: ",
  "巢穴不再有盡頭，因為你的燈就是它的盡頭。它安靜下來，像是睡了。": "The nest no longer has an end, because your lamp is its end. It falls quiet, as if asleep.",
  "巢穴入口的影子連頭都沒轉。你的燈剛亮起，就滅了。": "The shade at the nest entrance didn't even turn its head. Your lamp had just lit, and it went out.",
  "巢穴的一部分": "Part of the nest",
  "已匯入遊玩紀錄（已和現有紀錄合併，成就": "Play record imported (merged with the existing record; achievements ",
