  "影子被召喚出來": "The shades were summoned",
  "影子認得你": "The shades recognize you",
  "心神迷亂！射擊散開、視野變窄": "Mind adrift! Shots scatter and sight narrows",
  "成就還不夠（需要": "Not enough achievements (need ",
