  "投入 3 燈芯換一個強化（只能用一次）": "Throw in 3 wicks for an upgrade (one use only)",
  "拉一下：燈火 +1、燈芯 +6（只能用一次）": "Pull: lamplight +1, wicks +6 (one use only)",
  "按下：立刻叫出下一波敵人（只能用一次）": "Press: call the next wave of enemies right now (one use only)",
  "按下：震退並傷害場上所有敵人（Boss 傷害較少），並清除敵方子彈（只能用一次）": "Press: knocks back and damages every enemy on the field (less to bosses) and clears enemy bullets (one use only)",
  "攤位冷卻中：還要再移動": "Stall cooling down: move another ",
  "攻擊鍵 取代": "Attack key replaces",
  "攻擊間隔 −28%（占 2 層，最多 4 層）": "Attack interval −28% (takes 2 stacks, max 4 stacks)",
  "敵人凍結了": "Enemies frozen",
  "敵人如果落到你身後、超出畫面，就會消失，變成「雜念」。\n畫面上方的雜念條滿了，你會「迷亂」6 秒：子彈散開、視野只剩中間一圈。\n打倒敵人不會增加雜念；放著不管、一路往前跑，才會。": "Enemies that fall behind you and off-screen vanish and become “Distractions”.\nWhen the Distraction bar at the top fills, you become “Confused” for 6 s: shots scatter and sight shrinks to a small circle.\nDefeating enemies doesn't add Distraction; ignoring them and running ahead does.",
  "敵人退走了。打倒約": "The enemies retreated. Defeat about ",
  "星圖還在充能（還要": "The star chart is still charging (",
  "星陣！衝擊波與 5 秒星障（還剩": "Star Array! Shockwave and 5 s star barrier (",
  "時間到，Boss 退走了……什麼也沒得到": "Time's up, the boss retreated… nothing gained",
  "時間到，Boss 退走了（已得到第一份獎勵）": "Time's up, the boss retreated (first reward already earned)",
  "暗影巢穴：深度": "Shadow Nest: depth ",
  "更深的地方還有東西在動。": "Something still stirs deeper down.",
  "最深處的光靜靜等著，要由你決定它的去向。": "The light at the very bottom waits quietly; it is up to you to decide where it goes.",
  "有一道黑色的業障牆從起點慢慢往前推。\n被追上會持續扣血，所以不能停在原地太久。\n走進「道場」時，業障牆會暫停。": "A black wall of karma slowly advances from the start.\nBeing caught drains HP continuously, so don't stay in place too long.\nWhen you enter a “dojo”, the karma wall pauses.",
  "業障牆追上來了——往前走，到道場才會停": "The karma wall has caught up — keep moving; it only stops at a dojo",
  "業障牆：從後面推來": "Karma Wall: pushes in from behind",
  "極地的寒氣更重了": "The polar chill grows heavier",
  "次攻擊有加成": " attacks are boosted",
  "次（距離傳說保底還有": " times (to the legendary pity: ",
  "每層有三個道場，裡面沒有敵人。\n中間蒲團：站著不動、按住 F 約 2 秒，雜念清空。\n右邊木魚：按 F 出現縮圈，圈縮到最小時再按 F＝雜念清空，否則減半（每個木魚 3 次）。\n左邊佛龕：參拜一次，得到一份隨機回禮。": "Each floor has three dojos with no enemies inside.\nCenter cushion: stand still and hold F for about 2 s to clear Distraction.\nRight wooden fish: press F to show a shrinking ring; press F again when it is smallest = Distraction cleared, otherwise halved (3 uses per fish).\nLeft shrine: worship once to get a random gift.",
  "毒孢子飄了出來": "Poison spores drift out",
