  "沙刺突起！": "Sand spikes jut up!",
  "沙塵鬼捲了起來": "The dust fiend swirls up",
  "深處的影子不再撲上來，而是讓出一條路，直到你的燈熄滅。牠們似乎有點惋惜。": "The shades deep down no longer pounce, but step aside to let you pass, until your lamp goes out. They seem a little regretful.",
