  "警鈴大作！更多影子湧進來了（這間掉落變多）": "警報が鳴り響く!さらに多くの影が押し寄せる(この部屋はドロップ増加)",
  "狂亂裝置啟動！10 秒內它會朝四面亂射——敵人和你都會受傷": "狂乱装置が起動!10秒間、四方八方に乱射する——敵もあなたもダメージを受ける",
  "復活點已設定：這一局倒下時，會在這裡以半血復活一次（新的會取代舊的）": "復活地点を設定しました:今回のプレイで倒れると、ここで体力半分で一度復活します(新しいものが古いものに置き換わります)",
