  "（占 2 層上限）": "(上限の2段ぶんを占める)",
  "（占 2 層）": "(2段ぶんを占める)",
  "第 1 層：": "Lv1:",
  "第 2 層：": "Lv2:",
  "最大血量 +1，並恢復 1": "最大HP+1、さらに1回復",
  "傷害 +20%": "ダメージ+20%",
  "移動速度 +10%": "移動速度+10%",
  "攻擊間隔 -12%": "攻撃間隔-12%",
  "燈光範圍 +15%": "灯光範囲+15%",
  "子彈多穿透 1 隻敵人；本來就會穿透的武器改為傷害 +15%": "弾が敵をさらに1体貫通する。もともと貫通する武器はダメージ+15%になる",
  "子彈變大 25%，更好命中": "弾が25%大きくなり、当てやすくなる",
  "攻擊範圍 +20%：近戰、光束、長鞭與子彈射程都變長": "攻撃範囲+20%:近接・ビーム・長鞭・弾の射程がすべて伸びる",
  "燈芯的吸引與撿取範圍變大（吸引 +70、撿取 +18 像素；": "灯芯の吸引・拾得範囲が広がる(吸引+70、拾得+18px;",
  "暴擊率 +10%，暴擊造成 1.8 倍傷害": "会心率+10%、会心は1.8倍ダメージ",
  "職業技能冷卻 −12%": "職業スキルのクールダウン-12%",
  "職業技能的範圍與傷害 +20%": "職業スキルの範囲とダメージ+20%",
  "光爆結束 0.5 秒後再放出一道半徑 60% 的光波，傷害 1": "光爆が終わって0.5秒後に、半径60%の光波をもう一度放つ。ダメージ1",
