  "在彼岸連續擊敗 6 隻鏢影，期間沒被飛鏢打中（可獲得彼岸花提燈）": "彼岸で矢影を6体連続で倒し、その間ダーツに当たらない(彼岸花の提灯が手に入る)",
  "彼岸之主「模仿所有武器」那一招無傷通過（可獲得傳說造型）": "彼岸の主の「全武器を真似る」技を無傷で乗り切る(伝説コスメが手に入る)",
  "擊敗千手觀音（佛寺最後 Boss；可獲得小沙彌頭）": "千手観音を倒す(仏寺の最終ボス。小坊主の頭が手に入る)",
