  "尚未開放": "未開放",
  "造型機在": "コスメ機はロングランまたはDLC2のクリア後に開きます",
  "目前紙片：": "現在の紙片:",
  "紙片收入（每局結算）：基本 5；通關 +10；每個新成就 +5；長線作戰每層 +3（追加層每層 +5）。": "紙片収入(1プレイごとに精算):基本5、クリア+10、新しい実績ごとに+5、ロングランは1階層ごとに+3(追加階層は+5)。",
  "（合成）": "(合成)",
  "（重複 → 紙屑 +": "(重複→紙くず +",
  "（新）": "(新)",
  "還沒有抽取結果。": "まだ抽選結果がありません。",
  "　已擁有 ": "　所持 ",
