  " 次（距離傳說保底還有 ": " 回(伝説の天井まで",
  "抽 1 次（10 紙片）": "1回引く(紙片10)",
  "十連抽（90 紙片，至少 1 個稀有）": "10連(紙片90、レア以上が最低1つ)",
  "測試：＋100 紙片": "テスト:紙片+100",
  "合成：用紙屑換一件還沒有的　": "合成:紙くずで持っていないものと交換　",
  "開啟合成選單（紙屑 ": "合成メニューを開く(紙くず ",
  "自製造型": "自作コスメ",
  "　每個部位（頭部／身體／燈具／掛飾）限 1 個，匯入代碼合成；每個部位首次解鎖花 10 紙片，之後免費更換。": "　部位(頭/体/ランプ/飾り)ごとに1つまで。コードを読み込んで合成する。部位ごとに初回の解放は紙片10、その後は無料で変更できる。",
  "貼上 LKC1:{…} 代碼": "LKC1:{…} のコードを貼り付ける",
  "匯入合成": "読み込んで合成",
  "填入範例代碼": "サンプルコードを入力",
  "格式：LKC1:{\"s\":部位,\"n\":名稱,\"c\":主色,\"c2\":副色,\"p\":[[x,y],…],\"q\":[[x,y],…]}；p 為主多邊形（3～16 點、座標 -24～24，原點在該部位錨點，y 向下），q 為選填的副色多邊形。": "形式:LKC1:{\"s\":部位,\"n\":名前,\"c\":主色,\"c2\":副色,\"p\":[[x,y],…],\"q\":[[x,y],…]}。p は主ポリゴン(3〜16点、座標 -24〜24、原点はその部位のアンカー、y は下向き)、q は任意の副色ポリゴン。",
  "機率：普通 70%、稀有 25%、傳說 5%；每 30 抽保底 1 個傳說；重複的外觀變成紙屑（普通 1、稀有 3、傳說 10）；合成價：普通 5、稀有 15、傳說 40 紙屑。抽到的外觀到「造型」頁裝備（頭飾、身衣、燈飾、小飾品四欄）。": "確率:通常70%、レア25%、伝説5%。30回ごとに伝説1つが保証される。重複した見た目は紙くずになる(通常1、レア3、伝説10)。合成価格:通常5、レア15、伝説40紙くず。引いた見た目は「コスメ」ページで装備する(頭飾り、衣装、灯飾り、小物の4枠)。",
