  "最初的那一盞，顏色像傍晚的窗。": "最初の一灯。夕暮れの窓のような色。",
  "通關的人，才認得這種冷靜的光。": "クリアした人だけが、この静かな光を知っている。",
  "打倒五百隻影子之後，燈學會了安靜地發亮。": "五百の影を倒した後、灯は静かに光ることを覚えた。",
  "三位同伴的光混在一起，就是這個顏色。": "三人の仲間の光が混ざると、この色になる。",
  "洗過很多次，還是看得出來，是走過很多路的紅。": "何度も洗ったのにまだ分かる。たくさんの道を歩いてきた赤。",
  "沒有受過傷的人，才配得上這片海。": "傷ひとつない人だけが、この海にふさわしい。",
  "每個職業都走完一遍，連披風都鍍上了光。": "すべての職業を歩ききって、マントまで光で金メッキされた。",
  "只差一個人，就能走完。": "あと一人で、歩ききれる。",
  "走得越遠，披風就越長。": "遠くへ行くほど、マントは長くなる。",
  "折過一千隻紙鶴，願望還是同一個。": "千羽の鶴を折っても、願いは同じひとつ。",
  "風一來，扇子自己就開了。": "風が来ると、扇はひとりでに開く。",
  "雨天擋雨，晴天擋太亮的燈。": "雨の日は雨を、晴れの日は明るすぎる灯を防ぐ。",
  "別人的羽毛，自己的故事。": "他人の羽根、自分の物語。",
  "第一刀，總是最猶豫。": "最初の一刀は、いつも一番ためらう。",
  "剪下去的，都開成了花。": "切り落としたものは、すべて花になって咲いた。",
  "船不用水，用想像。": "船は水ではなく、想像で進む。",
  "折到最後一次，才發現是王冠。": "最後に折ったとき、王冠だと気づいた。",
  "透明的，所以每一滴都藏不住。": "透明だから、一滴残らず隠せない。",
  "燈油是最貴的，所以壺也要。": "灯油は一番高いから、壺もそうでなければ。",
  "盾碎過很多次，金邊是補上去的。": "盾は何度も砕けた。金縁は継ぎ足したもの。",
  "孩子們說，那是把星星關在罩子裡。": "子どもたちは言う、星を笠の中に閉じ込めたのだと。",
  "她說，這樣燈火看起來比較有精神。": "彼女は言う、こうすると灯火が元気そうに見えるのだと。",
  "燈芯留太長，就變成了火。": "灯芯を長く残しすぎると、炎になる。",
  "面具後面的人，從來不說自己是誰。": "仮面の後ろの人は、決して自分が誰かを言わない。",
  "彎彎的，像一盞還沒點亮的燈。": "曲がった形は、まだ灯っていないランプのよう。",
  "雪落在鐘上，聲音就變軟了。": "雪が鐘に落ちると、音がやわらかくなる。",
  "敲一下，整座山都聽見。": "一度打てば、山じゅうが聞く。",
  "永遠朝著燈的方向。": "いつも灯の方を向いている。",
  "開店的人，也得先學會揉麵。": "店を開く人も、まずは生地のこね方を学ばなければ。",
  "生意興隆，通四海。": "商売繁盛、四海に通ず。",
  "字寫壞了，就把燈蓋上，裝作什麼也沒發生。": "字を書き損じたら、灯を覆って、何事もなかったふりをする。",
  "開在河的另一邊，卻替這一邊照著路。": "川の向こう岸に咲いているのに、こちら側の道を照らしてくれる。",
  "每一塊積木，都替你記著一個字。": "ブロックはひとつひとつ、あなたのために文字をひとつ覚えている。",
  "花開的時候，沒有誰在數日子。": "花が咲くとき、誰も日数を数えない。",
  "遮得住太陽，遮不住想說話的眼睛。": "太陽は遮れても、話したがる目は遮れない。",
  "有人點了很久，從沒想過要熄。": "誰かがずっと昔に灯し、消そうと思ったことがない。",
  "飄過去的，都是放下了的。": "漂っていったものは、手放されたもの。",
  "洗了很多次，所以什麼都不再執著。": "何度も洗ったから、何にも執着しない。",
  "翻開的那一頁，永遠是你還沒讀過的。": "開いたページは、いつもまだ読んでいないページ。",
  "擺渡的人不說話，只負責把你送到岸邊。": "渡し守は何も言わず、あなたを岸辺まで送るだけ。",
  "它不屬於這一岸，所以特別紅。": "こちらの岸のものではないから、とりわけ赤い。",
  "頭上的三個點，是三個放下的念頭。": "頭の三つの点は、三つの手放した想い。",
  "泥裡長出來，卻一點也不髒。": "泥から生えたのに、少しも汚れていない。",
  "一針一線，都是別人放下的東西。": "一針一糸、誰かが手放したものでできている。",
  "勝利的人不一定是最強的，是走出迷宮的。": "勝者は最強とは限らない、迷宮を出た者だ。",
  "頭盔上的紅羽毛，是從碎掉的陶罐裡撿來的。": "兜の赤い羽根は、割れた壺から拾ってきたもの。",
  "雙耳瓶裡裝的不是酒，是一整個港口的黃昏。": "双耳壺に入っているのは酒ではなく、港ひとつぶんの夕暮れ。",
  "一點橄欖油，就能點亮整個下午。": "オリーブ油が少しあれば、午後ひとつ照らせる。",
  "神祇們都說，這件很適合你。": "神々は皆、これはあなたに似合うと言う。",
  "最後一顆櫻桃，總是留給戴帽子的人。": "最後のさくらんぼは、いつも帽子をかぶった人のために取っておく。",
  "融化之前，每一層顏色都很認真。": "溶ける前は、どの色の層も真剣だ。",
  "畫面有點雪花，可是你的臉很清楚。": "画面は少し雪模様だが、あなたの顔ははっきり見える。",
  "接住的每一個球，都變成一枚硬幣。": "キャッチしたボールは、すべて1枚のコインになる。",
  "擋住的是光，看清的是距離。": "遮るのは光、見えるようになるのは距離。",
  "視野裡的數字，永遠比你快一步。": "視界の数字は、いつもあなたより一歩先にいる。",
  "河上開了一朵花，是給迷路的人看的。": "川に花が一輪咲いた。迷った人に見せるために。",
  "一盞接一盞，全是同行的人。": "一灯また一灯、みんな道連れ。",
  "抱著它，連噩夢都會睡著。": "これを抱けば、悪夢さえ眠りにつく。",
  "醒著的人，才覺得這是夢遊。": "起きている人だけが、これを夢遊だと思う。",
