  "死亡所在的房間：": "死亡した部屋：",
  "W／S 選項目，A／D 換造型，F 返回。第一列可以直接換職業（最後一列是該職業的專屬造型）；造型只改外觀，灰色的在成就或通關後解鎖": "W/Sで項目選択、A/Dで見た目変更、Fで戻る。最上段でクラス変更（最下段はそのクラス専用の見た目）。見た目は外観のみで、灰色は実績かクリアで解放されます",
  "F 返回。死因從 v2.12 開始記錄；下方的「遊玩遙測」從 v2.34 開始累積，可隨遊玩紀錄匯出匯入": "Fで戻る。死因はv2.12から記録、下の「プレイ計測」はv2.34から蓄積され、プレイ記録とともに書き出し・読み込みできます",
  "F 返回。紙片只能用在造型機，沒有真錢，也不影響強度": "Fで戻る。紙片はガチャ専用で、実際のお金とは無関係、強さにも影響しません",
  "F 返回。遊玩紀錄＝成就、統計、造型、設定、遙測；匯入時與目前資料合併（取較大值）": "Fで戻る。プレイ記録＝実績・統計・見た目・設定・計測。読み込み時は現在のデータと統合（大きい方を採用）",
  "存檔：": "セーブ:",
  "（回到選單按「繼續上次存檔」）": "（メニューで「前回のセーブから続ける」を押す）",
  "目前沒有存檔（每一層開始時自動存檔，死亡或通關後清除）": "セーブはありません（各階層の開始時に自動保存、死亡かクリアで消去）",
  "　｜資料夾：已連結": "　｜フォルダ：連携済み",
  "局、通關": " 回、クリア ",
  "次、遊玩": " 回、プレイ ",
  "；紙片": "；紙片 ",
  "；成就": "；実績 ",
  "；長線歷史最遠 第 ": "。ロングラン過去最高 第 ",
  "遊戲中途離開（匯出目前進度）請在遊戲中的暫停頁操作。": "ゲーム中の中断（現在の進行の書き出し）はポーズ画面から行ってください。",
  "W／A 上一頁，S／D 下一頁，E 切換已達成／未達成，Q 切換分類，F 返回。達成後可以解鎖造型": "W/Aで前のページ、S/Dで次のページ、Eで達成/未達成切替、Qでカテゴリ切替、Fで戻る。達成すると見た目が解放されます",
  "這個條件下沒有成就。": "この条件の実績はありません。",
