  "全軍出擊！": "全軍、出撃!",
  "箭雨！": "矢の雨!",
  "狼人低吼——衝撞來了，往旁邊閃！": "狼男が低く唸る——突進が来る、横に避けろ!",
  "利爪！": "鋭い爪!",
  "嚎叫——蝙蝠被召來了！": "遠吠え——コウモリが呼ばれた!",
  "月下重擊！": "月下の重撃!",
  "不給糖就搗蛋：敲門試試運氣": "トリック・オア・トリート:ドアを叩いて運試し",
  "不給糖就搗蛋": "トリック・オア・トリート",
  "門已經關上了": "ドアはもう閉まりました",
  "敲一次門：45% 給糖（強化＋燈芯）、30% 搗蛋（出現幾隻小怪，打倒有燈芯）、25% 只給一點燈芯；只能一次": "ドアを一度叩く:45%でお菓子(強化+灯芯)、30%でいたずら(小さな手下が数体出現、倒すと灯芯)、25%で少しの灯芯。1回のみ。",
  "F 敲門": "F ドアを叩く",
  "給糖！強化「": "お菓子だ!強化「",
  "搗蛋！小怪撲出來了（先收下 8 燈芯）": "いたずら!小さな手下が飛び出した(先に灯芯8本を受け取る)",
  "門縫裡塞出幾顆糖：燈芯 +4": "ドアの隙間からお菓子がいくつか出てきた:灯芯+4",
  "幽靈商人：用燈芯換一把武器": "幽霊の商人:灯芯と武器を交換",
  "幽靈商人": "幽霊の商人",
  "他已經飄走了": "彼はもう漂って去りました",
  "花 8 燈芯，從他的斗篷下拿到一把隨機武器（你身上沒有的）；只能一次": "灯芯8本で、彼のマントの下からランダムな武器(未所持のもの)を受け取る。1回のみ。",
  "F 購買（8 燈芯）": "F 購入(灯芯8本)",
  "他沒有你需要的東西": "彼にはあなたの必要な物がありません",
  "得到武器：": "武器を入手:",
  "鬼故事：站在營火旁聽完 6 秒": "怪談:たき火のそばで6秒間聞く",
  "站在營火旁邊（150 像素內）聽 6 秒；離開會重新計時。結局：安心（回血＋燈芯）、勇氣（技能冷卻重置）、或被嚇到（出現幾隻小怪，但有大量燈芯）": "たき火から150ピクセル以内に立って6秒間聞く。離れるとタイマーが最初からになる。結末:安心(回復+灯芯)、勇気(スキルのクールダウンリセット)、驚き(小さな手下が数体出るが、灯芯がたっぷり)",
  "萬聖節（DLC5）": "ハロウィン(DLC5)",
  "萬聖節": "ハロウィン",
  "鬼屋的大門無聲地打開。巨大的南瓜頭在黑暗裡亮起，裹著床單的影子飄了過來。": "お化け屋敷の大扉が音もなく開く。巨大なカボチャの頭が暗闇に光り、シーツをまとった影が漂ってきた。",
  "你終於來了！我準備了一整年的鬼火，快——接好它們！": "やっと来たね!一年がかりで用意した鬼火だよ、さあ——受け止めて!",
  "墓地的地面隆起，一排排骷髏從土裡站起，整齊地轉向你。": "墓地の地面が盛り上がり、骸骨が列をなして土から立ち上がり、きれいにそろってあなたへ向き直る。",
  "全軍聽令——今晚，沒有人可以過這座橋！": "全軍に告ぐ——今夜、この橋を渡らせるな!",
  "只要骷髏還站著，軍團長就不怕任何攻擊。": "骸骨が立っているかぎり、軍団長はどんな攻撃も恐れない。",
  "雲被風推開，滿月露了出來。山丘上，有什麼東西慢慢站起身。": "風が雲を押しのけ、満月が顔を出す。丘の上で、何かがゆっくりと立ち上がった。",
  "月亮……真亮。你的燈，也很亮。可惜，我今晚不想被照著。": "月が……明るいな。お前の灯も明るい。だが残念だ、今夜は照らされたくない。",
  "牠在月光下會回血——不要給牠喘息的機會。": "やつは月光の下で回復する——息つく暇を与えるな。",
  "骷髏會重組一次——再補一刀": "骸骨は一度だけ再び組み上がる——もう一撃加えろ",
  "南瓜燈杖": "カボチャ灯の杖",
  "單發的南瓜火球，傷害高（萬聖節專屬，類似燈焰杖）": "単発のカボチャの火球。高ダメージ(ハロウィン専用。灯焔杖に似る)",
  "蝙蝠弓": "コウモリの弓",
  "按住連射小蝙蝠，射速快（萬聖節專屬，類似螢火弓）": "長押しで小さなコウモリを高速連射(ハロウィン専用。蛍火弓に似る)",
  "死神鐮刀": "死神の鎌",
  "大範圍的弧形揮砍（萬聖節專屬，類似提燈刃）": "広範囲の弧を描く斬撃(ハロウィン専用。提灯刃に似る)",
  "幽靈霰彈": "幽霊の散弾",
  "五發幽靈散射，近距離很痛（萬聖節專屬，類似霰光杖）": "幽霊を5発散らして撃つ。近距離で強烈(ハロウィン専用。霰光杖に似る)",
  "貫穿一整排敵人的骨頭長矛（萬聖節專屬，類似穿光矛）": "一列の敵を貫く骨の長槍(ハロウィン専用。穿光槍に似る)",
  "鬼火燒盡": "鬼火燃え尽きる",
  "萬聖節：擊敗南瓜燈幽靈王": "ハロウィン:カボチャ灯の幽霊王を倒す",
  "解散軍團": "軍団解散",
  "萬聖節：擊敗骷髏軍團長": "ハロウィン:骸骨軍団長を倒す",
  "月下不留情": "月下に容赦なし",
  "萬聖節：擊敗狼人": "ハロウィン:狼男を倒す",
  "膽大心細": "大胆かつ繊細",
  "萬聖節：同一局完成召喚祭壇與墓園夜襲": "ハロウィン:1回のプレイで召喚の祭壇と墓地の夜襲を両方完了する",
  "天快亮了。下一個節日的鈴聲，已經在路的盡頭響起。": "夜明けが近い。次のお祭りの鈴の音が、道の果てですでに鳴っている。",
  "今年的萬聖節，是第一次，有人陪我們到天亮。": "今年のハロウィンは、初めて誰かが夜明けまで一緒にいてくれた。",
  "所有的南瓜燈同時暗了下去，天邊露出一點魚肚白。你的燈，還亮著。": "すべてのカボチャのランタンが一斉に暗くなり、空の端が白んできた。あなたの灯は、まだともっている。",
  "雪從傍晚下到現在，整座山谷安靜得像被棉被蓋住。遠處，聖誕樹上的燈一串一串地亮了。": "雪は夕方から降り続き、谷じゅうが布団をかぶせたように静まり返っている。遠くでは、クリスマスツリーの灯りが一連ずつともっていく。",
  "提燈的旅人！北極工坊的玩具全跑出來了——幫我們收拾一下好嗎？": "提灯の旅人さん!北極工房のおもちゃが全部逃げ出しちゃったの——片付けを手伝ってくれない?",
  "第二個雪夜，鈴聲變得有點走調。煙囪冒著煙，卻沒有人在家。": "二つ目の雪の夜、鈴の音が少し調子外れになった。煙突から煙は出ているのに、家には誰もいない。",
  "最大的那一位在雪橇旁邊等你。他沒有生氣，只是……今年沒有人拆他的禮物。": "いちばん大きなあの人は、そりの横であなたを待っている。怒っているのではない。ただ……今年は誰も彼のプレゼントを開けてくれなかったのだ。",
  "聖誕卡片：親愛的老人，我今年不要玩具，只想要有人陪我拆禮物。": "クリスマスカード:親愛なるおじいさん、今年はおもちゃはいりません。プレゼントを一緒に開けてくれる人がほしいです。",
  "聖誕卡片：薑餅人說，他不怕烤箱，只怕被咬掉頭的那一瞬間。": "クリスマスカード:ジンジャーブレッドマンは言う。オーブンは怖くない。怖いのは、頭をかじられるその瞬間だけだと。",
  "聖誕卡片：胡桃鉗的嘴巴會張開，不是要咬人，是想說一句話。": "クリスマスカード:くるみ割り人形が口を開けるのは、噛みつくためじゃない。何か言いたいことがあるからだ。",
  "聖誕卡片：最亮的那顆星星，其實是別人替你留的燈。": "クリスマスカード:いちばん明るい星は、実は誰かがあなたのために残しておいた灯だ。",
