  "每顆蛋 4 燈芯（共 3 顆）：燈芯、燈油或強化；孵滿 3 顆得燈火 +1 與精良強化。已孵": "卵1つにつき灯芯4本(計3個):灯芯、灯油、または強化。3個とも孵すと灯火+1と上等強化。孵した数:",
  "按 F 打翻顏料：巨大的彩繪羊與 4 隻小怪出現；全部打倒得一把武器與燈芯": "Fで絵の具をひっくり返す:巨大な彩色の羊と小さな手下4体が現れる。全て倒すと武器と灯芯が得られる",
