  "站在花園旁（150 像素內）等 6 秒，離開會倒退。結局：回血加燈芯／技能冷卻重置加強化／燈芯 +15": "花園から150ピクセル以内に立って6秒間待つ。離れると進行が戻る。結果:回復+灯芯/スキルのクールダウンリセット+強化/灯芯+15",
