  "花 3 燈芯翻開草叢：50% 強化、30% 燈芯 +8、20% 只有一朵花（燈芯 +1）；只能一次": "灯芯3本で草むらを探る:50%で強化、30%で灯芯+8、20%で花一輪のみ(灯芯+1)。1回のみ。",
