  "花叢裡一對長耳朵緩緩升起，後面是比樹還高的白色身影。": "花の茂みから長い耳が一対ゆっくり立ち上がり、その後ろに木より背の高い白い影が見える。",
  "我把春天藏好了……你找得到，就拿去吧！": "春はちゃんと隠したよ……見つけられたら、持っていっていいよ!",
  "稻草窩裡，一隻巨大的母雞站了起來，腳邊擠滿了毛茸茸的小雞。": "わらの巣の中で、巨大なめんどりが立ち上がる。足元にふわふわのひよこがぎゅうぎゅうに集まっている。",
  "咕咕！誰都不准碰我的孩子！": "コッコッ!私の子供たちには誰も触らせないよ!",
  "只要小雞還圍著，雞媽媽就不怕傷害。": "ひよこが周りにいるかぎり、お母さんニワトリはどんなダメージも恐れない。",
  "草地中央，一顆粉紅色的巨蛋靜靜立著，蛋殼上有一道細細的裂痕。": "草地の中央に、ピンク色の巨大な卵が静かに立っている。殻には細いひびが一筋入っていた。",
  "咚……咚……裡面的人，等了好久，好久。": "ドン……ドン……中にいる者は、長い、長いあいだ待っていた。",
  "蛋殼裂開的瞬間，是最脆弱的時候。": "殻が割れた瞬間こそ、いちばん弱い時だ。",
