  "：技能冷卻重置、強化「": ":スキルのクールダウンをリセット、強化「",
  "4 燈芯（共 3 個）：燈芯、燈油或強化；滿 3 個得燈火 +1 與精良強化。已用": " 灯芯4本(計3個):灯芯、灯油、または強化。3個とも満たすと灯火+1と上等強化。使用済み:",
  "按 F 開始：巨大的舞獅（精英）與 4 隻小怪出現；全部打倒得一把武器與燈芯": "Fで開始:巨大な獅子舞(エリート)と小さな手下4体が現れる。全て倒すと武器と灯芯が得られる",
  "按 F 獻一份供品（最多 5 份）：燈芯、燈油，偶爾驚動怪物": "Fで供え物を捧げる(最大5個):灯芯、灯油、たまに怪物を驚かせる",
  "站在旁邊（150 像素內）等 6 秒，離開會倒退。結局：回血加燈芯／技能冷卻重置加強化／燈芯 +15": "そばの150ピクセル以内に立って6秒間待つ。離れると進行が戻る。結果:回復+灯芯/スキルのクールダウンリセット+強化/灯芯+15",
  "旁邊等 6 秒就好": "のそばで6秒間待つだけ",
