  "年獸衝街——看缺口！": "年獣が通りを突進してくる——隙間を見ろ!",
  "煙火雨！": "花火の雨!",
  "鑼鼓聲突然停了。街口的燈籠被一陣腥風吹得亂晃，一個火紅的巨影壓了過來。": "銅鑼と太鼓の音が突然止んだ。通りの入口の提灯が生臭い風に激しく揺れ、真っ赤な巨大な影がのしかかってくる。",
  "吼——每年今天，都有人敢在我的地盤放炮！": "ウオォォ——毎年この日になると、俺の縄張りで爆竹を鳴らす奴がいる!",
  "舞龍隊長": "龍舞隊長",
  "爆竹精列隊！": "爆竹の精、整列!",
  "鑼鼓加速——爆竹精衝鋒！": "銅鑼が加速——爆竹の精が突撃する!",
  "整串鞭炮點燃！": "爆竹が一連ごと点火された!",
  "彩球彈！": "カラーボール弾!",
  "長長的龍身在街上蜿蜒，後頭跟著一整排蹦蹦跳跳的爆竹精。": "長い龍の体が通りをうねり、後ろにはぴょんぴょん跳ねる爆竹の精がずらりと続いている。",
  "龍頭要走到哪，隊伍就跟到哪！誰都別想擋路！": "龍の頭が行く先へ、隊列はついていく!誰も道をふさぐな!",
  "只要爆竹精還圍著，龍頭就不怕傷害。": "爆竹の精が周りにいるかぎり、龍の頭はどんなダメージも恐れない。",
  "巨型燈籠": "巨大提灯",
  "吹熄燈籠": "提灯を吹き消せ",
  "燈籠滾來——撞完後燈光大亮 3 秒是弱點，傷害 ×2！": "提灯が転がってくる——激突後、3秒間明るく輝く間は弱点、ダメージ×2!",
  "小燈籠亮起來了！": "小さな提灯がともった!",
  "燈火環！": "灯火の輪!",
  "燈籠重壓！": "提灯の圧殺!",
  "廣場中央，一盞比房子還高的大紅燈籠緩緩亮起，上面的「財」字閃著金光。": "広場の中央で、家より高い大きな赤い提灯がゆっくりとともり、「財」の字が金色にきらめく。",
  "燈火不滅，年不散……想吹熄我，先讓我亮起來。": "灯が消えなければ、年は終わらない……吹き消したいなら、まず私を輝かせてみろ。",
  "牠燈光大亮的瞬間，是最脆弱的時候。": "明るく輝いた瞬間こそ、いちばん弱い時だ。",
  "爆竹精圍著龍頭——先清掉爆竹精，Boss 才會吃傷害": "爆竹の精が龍の頭を囲んでいる——先に爆竹の精を片付けないと、ボスにダメージが入らない",
  "猜燈謎：花 3 燈芯，猜一支謎": "灯謎当て:灯芯3本で謎を一つ当てる",
  "猜燈謎": "灯謎当て",
  "花 3 燈芯猜一支謎：50% 強化、30% 燈芯 +8、20% 只得一顆糖；只能一次": "灯芯3本で謎を一つ当てる:50%で強化、30%で灯芯+8、20%で飴一つだけ。1回のみ。",
  "燈謎已經猜過了": "灯謎はもう当てました",
  "猜中了": "正解",
  "安慰獎：燈芯 +8": "残念賞:灯芯+8",
  "猜錯了……送你一顆糖，燈芯 +1": "はずれ……飴を一つあげよう、灯芯+1",
  "舞獅表演：站在旁邊看 5 秒": "獅子舞:そばで5秒間見る",
  "舞獅表演": "獅子舞",
  "站在舞獅旁邊（150 像素內）看 5 秒，離開會倒退。看完：燈火 +1、燈芯 +10": "獅子舞から150ピクセル以内に立って5秒間見る。離れると進行が戻る。見終えると:灯火+1、灯芯+10",
  "表演結束了": "演技は終わりました",
  "好彩頭：燈火 +1、燈芯 +10": "縁起がいい:灯火+1、灯芯+10",
  "年夜飯攤：花 6 燈芯，吃一頓團圓飯": "年越し料理の屋台:灯芯6本で団欒の食事をとる",
