  "大範圍的弧形揮砍（春節專屬，類似提燈刃）": "広範囲の弧を描く斬撃(春節専用。提灯刃に似る)",
  "煙火筒": "花火筒",
  "單發的煙火彈，傷害高（春節專屬，類似燈焰杖）": "単発の花火弾。高ダメージ(春節専用。灯焔杖に似る)",
  "燈籠弓": "提灯の弓",
  "按住連射小燈籠火，射速快（春節專屬，類似螢火弓）": "長押しで小さな提灯の火を高速連射(春節専用。蛍火弓に似る)",
  "紅包散彈": "お年玉の散弾",
  "五發紅包散射，近距離很痛（春節專屬，類似霰光杖）": "お年玉を5発散らして撃つ。近距離で強烈(春節専用。霰光杖に似る)",
  "春聯長矛": "春聯の槍",
  "貫穿一整排敵人的長矛（春節專屬，類似穿光矛）": "一列の敵を貫く長槍(春節専用。穿光槍に似る)",
  "新年好幫手": "新年の小さな助っ人",
  "同一局完成紅包池與鞭炮坊": "1回のプレイでお年玉の池と爆竹工房を両方完了する",
  "小年獸": "小さな年獣",
  "爆竹串": "爆竹の連なり",
  "除夕的黃昏，整條街掛滿了紅燈籠。鑼鼓聲從遠處傳來，空氣裡有鞭炮與糖炒栗子的味道。": "大晦日の夕暮れ、通りじゅうに赤い提灯が掛かっている。遠くから銅鑼と太鼓の音が聞こえ、空気には爆竹と甘栗の匂いが漂う。",
  "提燈的旅人！爆竹自己跑出去了，年貨攤都被攪得亂七八糟——幫忙收拾一下吧！": "提灯の旅人さん!爆竹が勝手に飛び出して、年越しの品を売る屋台がめちゃくちゃなんだ——片付けを手伝っておくれ!",
  "夜越深，燈籠越亮，街上的人影卻越來越少。有些聲音，好像在等著什麼人回家。": "夜が深まるほど提灯は明るくなるのに、通りの人影はどんどん減っていく。誰かの帰りを待っているような声が、どこかから聞こえる。",
  "最大的那一盞燈籠，從傍晚就一直亮著。大家都說，那是在等一個沒回來的人。": "いちばん大きな提灯は、夕方からずっとともっている。みんな言う、帰ってこなかった人を待っているのだと。",
  "紅包便條：我把壓歲錢藏在枕頭下，結果過年那天，枕頭不見了。": "お年玉のメモ:お年玉を枕の下に隠したら、お正月の日に枕がなくなっていた。",
  "紅包便條：年獸其實不怕鞭炮，只是想有人陪牠守歲。": "お年玉のメモ:年獣は本当は爆竹が怖いんじゃない。ただ、年越しを一緒に過ごしてくれる人がほしいだけだ。",
  "紅包便條：舞獅的頭很重，但抬頭的人說，那是全年最輕的一天。": "お年玉のメモ:獅子舞の頭は重い。でも持ち上げている人は言う、一年でいちばん軽い日だと。",
  "紅包便條：燈籠不是為了照路，是為了讓遠方的人看見家。": "お年玉のメモ:提灯は道を照らすためじゃない。遠くにいる人に、家を見つけてもらうためのものだ。",
  "天亮了，燈籠一盞一盞熄了。新年好，旅人。": "夜が明け、提灯がひとつずつ消えていく。あけましておめでとう、旅人よ。",
  "街上的鞭炮碎屑像一地紅色的花瓣，你的燈在其中，安靜地亮著。": "通りに散らばった爆竹の紙くずは赤い花びらのようで、その中であなたの灯が静かにともっている。",
