  "月華扇！": "月華の扇!",
  "月暈環！": "月暈の輪!",
  "桂花旋風！": "金木犀の旋風!",
  "廣袖橫掃——看缺口！": "広い袖の薙ぎ払い——隙間を見ろ!",
  "月光雨！": "月光の雨!",
  "月光忽然變得很亮。庭院中央，一位白衣的身影懸在半空，袖子在無風的夜裡輕輕飄動。": "月の光が突然とても明るくなった。庭の中央に、白い衣の人影が宙に浮かび、風のない夜に袖がそっと揺れている。",
  "他說好中秋要上來看我。我等了一整晚，連他的影子都沒見到！": "あの人は中秋に会いに来ると約束したのに。一晩中待っても、影さえ見えなかった!",
  "……你替他來的嗎？那就先接我這一招吧！": "……あの人の代わりに来たの?それなら、まずこの一手を受けてみなさい!",
  "玉兔搗藥軍": "玉兎の薬搗き軍",
  "停下藥杵": "杵を止めろ",
  "月兔列隊！": "月ウサギ、整列!",
  "藥杵加速——月兔衝鋒！": "杵が加速——月ウサギが突撃する!",
  "全員出動！": "全員、出動!",
  "藥丸彈！": "薬丸弾!",
  "搗藥坊裡，巨大的玉兔高舉藥杵，身後跟著整排圓滾滾的小月兔。": "薬搗き工房で、巨大な玉兎が杵を高く掲げ、その後ろに丸々とした小さな月ウサギがずらりと並ぶ。",
  "兩位大人都在生氣，藥搗不好，我們也不敢停……你快走開！": "お二方とも怒っていて、薬がうまく搗けないけど、私たちは止める勇気もない……早く立ち去って!",
  "只要月兔還圍著，玉兔就不怕傷害。": "月ウサギが周りにいるかぎり、玉兎はどんなダメージも恐れない。",
  "吳剛的桂樹": "呉剛の桂の木",
  "砍倒桂樹": "桂の木を切り倒せ",
  "桂樹壓來——撞完後桂花紛落 3 秒是弱點，傷害 ×2！": "桂の木が倒れ込んでくる——激突後、花が舞い落ちる3秒間は弱点、ダメージ×2!",
  "桂花精冒出來了！": "金木犀の精が現れた!",
  "落花環！": "落花の輪!",
  "桂樹重壓！": "桂の木の圧殺!",
  "月光下，一棵高得看不見頂的桂樹，樹幹上插著一把生鏽的斧頭。": "月明かりの下、てっぺんが見えないほど高い桂の木が立ち、幹には錆びた斧が刺さっている。",
  "她說今晚會下來看這棵樹。我砍了一輩子，就是為了等這一刻——人呢？她沒來！": "彼女は今夜、この木を見に降りてくると言った。一生斧を振るってきたのは、この時のためなのに——どこだ?来なかった!",
  "桂花紛紛落下的瞬間，是最脆弱的時候。": "金木犀の花がはらはらと舞い落ちる瞬間こそ、いちばん弱い時だ。",
  "月兔們圍著玉兔——先清掉月兔，Boss 才會吃傷害": "月ウサギが玉兎を囲んでいる——先に月ウサギを片付けないと、ボスにダメージが入らない",
  "玉兔換藥：花 3 燈芯，換一包藥草": "玉兎の薬草交換:灯芯3本で薬草一包と交換",
  "玉兔換藥": "玉兎の薬草交換",
  "花 3 燈芯換一包藥草：50% 強化、30% 燈芯 +8、20% 只是普通桂花（燈芯 +1）；只能一次": "灯芯3本で薬草一包と交換:50%で強化、30%で灯芯+8、20%でただの金木犀(灯芯+1)。1回のみ。",
