  "賞月石凳": "月見の石のベンチ",
  "站在石凳旁（150 像素內）賞月 5 秒，離開會倒退。完成：燈火 +1、燈芯 +10": "石のベンチから150ピクセル以内に立って5秒間月を眺める。離れると進行が戻る。完了すると:灯火+1、灯芯+10",
