  "大範圍的弧形揮砍（中秋專屬，類似提燈刃）": "広範囲の弧を描く斬撃(中秋専用。提灯刃に似る)",
  "月餅砲": "月餅砲",
  "單發的月餅，傷害高（中秋專屬，類似燈焰杖）": "単発の月餅。高ダメージ(中秋専用。灯焔杖に似る)",
  "桂花弓": "金木犀の弓",
  "按住連射桂花，射速快（中秋專屬，類似螢火弓）": "長押しで金木犀を高速連射(中秋専用。蛍火弓に似る)",
  "玉兔散彈": "玉兎の散弾",
  "五發月光散射，近距離很痛（中秋專屬，類似霰光杖）": "月光を5発散らして撃つ。近距離で強烈(中秋専用。霰光杖に似る)",
  "桂枝長矛": "桂の枝の槍",
  "貫穿一整排敵人的桂枝長矛（中秋專屬，類似穿光矛）": "一列の敵を貫く桂の枝の長槍(中秋専用。穿光槍に似る)",
  "中秋小幫手": "中秋の小さな助っ人",
  "同一局完成拜月台與搗藥坊": "1回のプレイで月拝みの台と薬搗き工房を両方完了する",
  "月蝕輪": "月蝕の輪",
  "中秋夜，月亮大得像要掉進庭院裡。桂花的香味一陣一陣飄過來，遠處有人在烤肉、有人在猜燈謎。": "中秋の夜、月は庭に落ちてきそうなほど大きい。金木犀の香りが波のように漂い、遠くでは誰かが肉を焼き、誰かが灯謎を当てている。",
  "提燈的旅人！月餅和藥草全被打翻了，有些東西在庭院裡亂跑，請你幫忙收拾！": "提灯の旅人さん!月餅も薬草もひっくり返されて、庭で何かが走り回ってるの。片付けを手伝って!",
  "月越升越高，庭院的影子越拉越長。有兩個影子，一個在天的這一頭，一個在那一頭，怎麼也碰不到一起。": "月は高く昇り、庭の影はどんどん長くなる。二つの影があった。一つは空のこちら側に、もう一つはあちら側にいて、どうしても触れ合えない。",
  "嫦娥大人和吳剛大人，每年今天都在等彼此，可是每年都剛好錯過……今年他們都氣壞了。": "嫦娥様と呉剛様は、毎年この日にお互いを待っているのに、毎年ちょうどすれ違ってしまう……今年は二人ともカンカンなんです。",
  "月餅便條：我說好今晚會來，結果月亮太亮，我迷路了。": "月餅のメモ:今夜行くと約束したのに、月が明るすぎて道に迷ってしまった。",
  "月餅便條：桂樹砍不倒不是因為樹太硬，是因為我捨不得它倒。": "月餅のメモ:桂の木が倒れないのは、木が硬いからじゃない。倒したくないと、私が思っているからだ。",
  "月餅便條：兔子搗了一千年的藥，其實只是想找個人說說話。": "月餅のメモ:ウサギは千年も薬を搗き続けた。本当は、話し相手がほしかっただけ。",
  "月餅便條：月亮每個月都會變圓一次，等的人也是。": "月餅のメモ:月は毎月一度まんまるになる。待っている人も同じだ。",
  "……我看見他了。原來他的影子，一直就在樹下。": "……あの人が見えた。影はずっと、木の下にあったのね。",
  "她也在。原來她，一直就在月亮上面。": "彼女もいる。ずっと月の上にいたのか。",
  "你的燈光落在兩人之間，影子終於碰在了一起。庭院裡的桂花，落了一整夜。": "あなたの灯が二人の間に落ち、影がようやく触れ合った。庭の金木犀の花は、一晩じゅう降り続けた。",
  "織女岸": "織姫の岸",
  "星砂灘": "星砂の浜",
  "織布坊": "機織り工房",
