  "織梭飛舞——巨大的牛衝出來了！": "杼が舞う——巨大な牛が飛び出した!",
  "織布坊安靜了：織出了一把武器": "機織り工房が静まった:武器が織り上がった",
  "織布坊已安靜": "機織り工房は静まりました",
