  "跳蛙撲了個空（你沒有燈芯可偷）": "跳びガエルは空振りした(盗める灯芯がありません)",
  "貪吃鬼在吃掉在地上的食材！打倒它會吐出一部分": "食いしん坊が床の食材を食べている!倒せば一部を吐き出す",
