  "大廚端來一碗熱湯：燈火 +1、燈芯 +6": "料理長が熱いスープを持ってきた:灯火+1、灯芯+6",
  "大廚遞來一把廚具（地上的武器）": "料理長が調理器具を差し出した(床に置かれた武器)",
  "大廚塞給你一把燈芯 +14": "料理長が灯芯をひとつかみ握らせてくれた:+14",
