  "」，下一位登場！": "」、次の挑戦者が登場!",
  "」：冷卻": "」:クールダウン",
  "下一格的": "次の枠の",
  "下一格的「": "次の枠の「",
  "不選，返回": "選ばずに戻る",
  "主題：隨機": "テーマ:ランダム",
  "你多走了三層。那些路不是為了誰，只是燈想知道，自己還能照多遠。": "あなたは三階層よけいに歩いた。その道は誰のためでもない。ただ、灯が自分にはまだどこまで照らせるのかを知りたかっただけだ。",
  "你的影子留在了這一層。下一個走進來的人，會看見它替你提著燈。": "あなたの影はこの階層に残った。次に入ってきた人は、影があなたの代わりに灯を提げているのを目にするだろう。",
  "你看過了每一個世界的影子，它們也看過了你。再往下，就是重複。": "あなたはすべての世界の影を見てきた。影たちもあなたを見てきた。これより下は、ただの繰り返しだ。",
  "你聽見自己的腳步在更深處響起——那不是回聲，是下一批影子在模仿你。": "自分の足音がさらに奥で響くのが聞こえる——こだまではなく、次の影たちがあなたの真似をしているのだ。",
  "你走過了六層，燈芯卻比預期短得多。巢穴記住了你的味道。": "あなたは六階層を越えたが、灯芯は思ったよりずっと短い。巣窟はあなたの匂いを覚えた。",
  "修行路：一直往前": "修行の道:ひたすら前へ",
