  "召喚機關": "召喚の仕掛け",
  "可玩原型 v2.47　需要鍵盤與滑鼠，請用電腦開啟": "プレイ可能なプロトタイプ v2.47　キーボードとマウスが必要です。PCで開いてください",
  "可玩原型 v2.65　手機版：直向（上方畫面、下方操作區）與橫向皆可": "プレイ可能なプロトタイプ v2.65　スマホ版:縦向き(上が画面、下が操作エリア)と横向きの両方に対応",
  "同行通關了，但他還在猶豫（下次機率": "同行でクリアしたが、彼はまだ迷っている(次回の確率",
